    """Exact directed Steiner tree via subset DP (digraph Dreyfus-Wagner).

    dp[S][v] = min cost of a directed structure rooted at node v reaching
    every terminal in subset S. Singletons use reverse-Dijkstra distances;
    larger subsets merge two disjoint sub-subsets at a shared root, then a
    multi-source Dijkstra relaxes along incoming edges. Recipe pointers
    record how each value was achieved so the actual edge union can be
    reconstructed. The union counts shared edges once, so realized cost
    never exceeds the DP value. Returns the edge set, or None when
    infeasible or too many terminals (>12).
    """
    import heapq
    k = len(terms)
    if k == 0 or k > 12:
        return None
    INF = float("inf")
    rev = h.reverse(copy=False)
    size = 1 << k
    dp = [None] * size
    rec = {}
    for i, t in enumerate(terms):
        try:
            dist, pred = nx.single_source_dijkstra(rev, t, weight="cost")
        except Exception:
            return None
