            else:
                p = pred.get(v)
                rec[(1 << i, v)] = ("hop", p) if p is not None else None
        dp[1 << i] = d
    full = size - 1
    for S in range(1, full + 1):
        if S & (S - 1) == 0:
            continue  # singleton, already built
        best, bestrec = {}, {}
        s1 = (S - 1) & S
        while s1:
